import{_ as a,o as t,c as i,a4 as e}from"./chunks/framework.BBs01uty.js";const k=JSON.parse('{"title":"mall 项目的部署流程 & 最佳实践","description":"","frontmatter":{},"headers":[],"relativePath":"java-practice/09-deployment-practice.md","filePath":"java-practice/09-deployment-practice.md"}'),n={name:"java-practice/09-deployment-practice.md"};function l(d,s,p,o,r,h){return t(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="mall-项目的部署流程-最佳实践" tabindex="-1">mall 项目的部署流程 &amp; 最佳实践 <a class="header-anchor" href="#mall-项目的部署流程-最佳实践" aria-label="Permalink to &quot;mall 项目的部署流程 &amp; 最佳实践&quot;">​</a></h1><blockquote><p><strong>定位</strong>：以 mall 项目实际部署文件为蓝本，讲清&quot;一个 Spring Boot 项目从代码到线上&quot;的完整流程。mall 部署相关文件分散在 <code>document/</code> 下，本文把它们串成一条可操作的流水线。</p></blockquote><h2 id="一、部署全景-要部署哪些东西" tabindex="-1">一、部署全景（要部署哪些东西） <a class="header-anchor" href="#一、部署全景-要部署哪些东西" aria-label="Permalink to &quot;一、部署全景（要部署哪些东西）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基础设施（中间件）           应用服务              入口/日志</span></span>
<span class="line"><span>┌─────────────────┐   ┌──────────────────┐   ┌──────────────┐</span></span>
<span class="line"><span>│ mysql (3306)     │   │ mall-admin  (8080) │   │ nginx (80)    │</span></span>
<span class="line"><span>│ redis (6379)     │   │ mall-search (8081) │   │ logstash (4560 │</span></span>
<span class="line"><span>│ rabbitmq (5672)  │   │ mall-portal (8085) │   │  ~4563)       │</span></span>
<span class="line"><span>│ es (9200)        │   └──────────────────┘   │ kibana (5601)  │</span></span>
<span class="line"><span>│ mongo (27017)    │                          └──────────────┘</span></span>
<span class="line"><span>│ minio (9000/9001)│</span></span>
<span class="line"><span>└─────────────────┘</span></span></code></pre></div><p>对应 mall 的部署文件：</p><table tabindex="0"><thead><tr><th>文件</th><th>管什么</th></tr></thead><tbody><tr><td><code>document/docker/docker-compose-env.yml</code></td><td>基础设施全家桶（中间件）</td></tr><tr><td><code>document/docker/docker-compose-app.yml</code></td><td>应用服务（admin/search/portal）</td></tr><tr><td><code>document/docker/nginx.conf</code></td><td>统一入口（前端 + API 反代）</td></tr><tr><td><code>document/sh/run.sh</code> / <code>mall-*.sh</code></td><td>应用&quot;手动部署&quot;脚本（不用 compose 时）</td></tr><tr><td><code>document/sh/Dockerfile</code></td><td>应用镜像的构建定义</td></tr><tr><td><code>document/elk/logstash.conf</code></td><td>日志收集配置（logstash → ES）</td></tr></tbody></table><h2 id="二、前置-基础设施先起来" tabindex="-1">二、前置：基础设施先起来 <a class="header-anchor" href="#二、前置-基础设施先起来" aria-label="Permalink to &quot;二、前置：基础设施先起来&quot;">​</a></h2><p><strong>硬前提</strong>：应用启动前，它依赖的中间件容器必须存在（应用靠 <code>--link</code> / <code>external_links</code> 按主机名连它们）。</p><p><strong>方式 A：docker-compose 一键</strong>（推荐）</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> document/docker/docker-compose-env.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 一口气起 mysql/redis/nginx/rabbitmq/es/logstash/kibana/mongo/minio</span></span></code></pre></div><p><strong>方式 B：手动起</strong>（只要跑 mall-admin 就够）</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 或用 docker run 起 mysql/redis 两个</span></span></code></pre></div><blockquote><p><strong>不一定非用 env 文件</strong>，但&quot;中间件容器必须在&quot;是铁前提。env 只是最省事的&quot;一键全套&quot;。</p></blockquote><h2 id="三、应用镜像从哪来" tabindex="-1">三、应用镜像从哪来 <a class="header-anchor" href="#三、应用镜像从哪来" aria-label="Permalink to &quot;三、应用镜像从哪来&quot;">​</a></h2><p>镜像不是拉现成的，是<strong>自己打</strong>的：<code>openjdk:17 基础镜像 + 应用 jar</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>镜像名 mall/mall-admin:1.0-SNAPSHOT</span></span>
<span class="line"><span>        │      │            │</span></span>
<span class="line"><span>      仓库前缀 模块名      = maven 版本（\${project.version}）</span></span></code></pre></div><p><strong>两种打法</strong>（产物等价）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ① Maven 插件自动打（root pom 的 docker-maven-plugin，package 时执行）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 镜像名由 pom 配置：mall/\${project.name}:\${project.version}</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 基础镜像：&lt;from&gt;openjdk:17&lt;/from&gt;，入口：java -jar xxx.jar</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ② 手工 Dockerfile（document/sh/Dockerfile，和①等价）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> document/sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 把 mall-admin-1.0-SNAPSHOT.jar 放这</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mall/mall-admin:1.0-SNAPSHOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><h2 id="四、部署应用-两种方式" tabindex="-1">四、部署应用（两种方式） <a class="header-anchor" href="#四、部署应用-两种方式" aria-label="Permalink to &quot;四、部署应用（两种方式）&quot;">​</a></h2><p><strong>方式 A：docker-compose-app.yml</strong>（配合方式一的环境）</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> document/docker/docker-compose-app.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>应用容器通过 <code>external_links</code> 连 env 起的中间件（按容器名解析）：</p><ul><li>mall-admin → mysql + redis（<strong>注意：admin 依赖 redis</strong>，原版 app.yml 漏了，已补）</li><li>mall-search → es + mysql</li><li>mall-portal → redis + mongo + mysql + rabbitmq</li></ul><p><strong>方式 B：run.sh 手动</strong>（admin 示例，各模块有对应脚本）</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./document/sh/run.sh</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 内部：停旧容器 → 删旧镜像 → docker build → docker run</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># docker run -p 8080:8080 --link mysql:db --link redis:redis -e spring.profiles.active=prod ...</span></span></code></pre></div><p><strong>判断服务依赖的经验</strong>：compose 里&quot;没写&quot;不等于&quot;不依赖&quot;——<strong>以代码实际用了什么为准</strong>（如 grep <code>RedisService</code> 就能证明 admin 用 redis）。</p><h2 id="五、nginx-统一入口" tabindex="-1">五、nginx 统一入口 <a class="header-anchor" href="#五、nginx-统一入口" aria-label="Permalink to &quot;五、nginx 统一入口&quot;">​</a></h2><p>部署后用 nginx（env 里那个或自配的）统一对外：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 → nginx:80</span></span>
<span class="line"><span>  ├─ /             → 前端静态页面（mall-admin-web 打包产物）</span></span>
<span class="line"><span>  └─ /admin/...    → 反代到 mall-admin:8080</span></span></code></pre></div><p>配置见 <code>document/docker/nginx.conf</code>（静态资源目录 + API 反代）。对应前端：<strong>构建后产物丢 nginx 静态目录，API 走 nginx 反代到后端</strong>。</p><h2 id="六、elk-日志接入-可选" tabindex="-1">六、ELK 日志接入（可选） <a class="header-anchor" href="#六、elk-日志接入-可选" aria-label="Permalink to &quot;六、ELK 日志接入（可选）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应用（logback）→ TCP 发 4560-4563 → Logstash → ES → Kibana</span></span></code></pre></div><ul><li>应用侧：<code>logback-spring.xml</code> 已有 Logstash appender，开关是 <code>logstash.enableInnerLog</code>（默认 false）</li><li>部署侧：Logstash 的 input/output 在 <code>document/elk/logstash.conf</code>（监听 4560-4563，输出到 ES <code>localhost:9200</code>）</li><li>env 的 docker-compose 已含 es/logstash/kibana；logstash.conf 挂载为 <code>/mydata/logstash/logstash.conf</code></li></ul><p>开启日志平台：把 prod 配置的 <code>logstash.enableInnerLog</code> 设为 true 即可。</p><h2 id="七、端口速查" tabindex="-1">七、端口速查 <a class="header-anchor" href="#七、端口速查" aria-label="Permalink to &quot;七、端口速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端口</th><th>谁</th><th>说明</th></tr></thead><tbody><tr><td>8080</td><td>mall-admin</td><td>后台 API</td></tr><tr><td>8081</td><td>mall-search</td><td>搜索 API</td></tr><tr><td>8085</td><td>mall-portal</td><td>前台 API</td></tr><tr><td>80</td><td>nginx</td><td>统一入口</td></tr><tr><td>3306 / 6379</td><td>mysql / redis</td><td>基础</td></tr><tr><td>9200 / 5601</td><td>es / kibana</td><td>ELK</td></tr><tr><td>4560-4563</td><td>logstash</td><td>收日志</td></tr><tr><td>9000/9001</td><td>minio</td><td>文件存储</td></tr></tbody></table><h2 id="八、部署顺序-最佳实践" tabindex="-1">八、部署顺序 &amp; 最佳实践 <a class="header-anchor" href="#八、部署顺序-最佳实践" aria-label="Permalink to &quot;八、部署顺序 &amp; 最佳实践&quot;">​</a></h2><p><strong>标准顺序</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ① 起基础设施</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose-env.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ② 打应用镜像（mvn package 或 docker build）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mall-admin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -am</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ③ 起应用</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose-app.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或手动 ./document/sh/run.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ④ nginx 入口 + （可选）开 ELK 日志</span></span></code></pre></div><p><strong>最佳实践清单</strong>：</p><table tabindex="0"><thead><tr><th>实践</th><th>说明</th></tr></thead><tbody><tr><td>服务依赖以<strong>代码/配置</strong>为准</td><td>compose 文件可能过时（admin 依赖 redis 就曾漏写）</td></tr><tr><td>镜像版本和 maven 版本绑定</td><td><code>1.0-SNAPSHOT</code> 标识，升级代码要同步 tag</td></tr><tr><td>数据卷挂载持久化</td><td>mysql/redis 数据挂到 <code>/mydata/*</code>，容器删了数据不丢</td></tr><tr><td>环境变量区分 prod</td><td><code>-e spring.profiles.active=prod</code>，配置和代码分离</td></tr><tr><td>日志别只进容器</td><td>应用日志卷挂到宿主机，或接 ELK</td></tr><tr><td>部署前验证镜像</td><td><code>docker images</code> 确认有 <code>mall/mall-admin:1.0-SNAPSHOT</code></td></tr><tr><td>基础镜像用 openjdk:17</td><td>和 mall 的 Java 17 一致，别用旧 JDK 镜像</td></tr></tbody></table><h2 id="九、和本地开发的区别" tabindex="-1">九、和本地开发的区别 <a class="header-anchor" href="#九、和本地开发的区别" aria-label="Permalink to &quot;九、和本地开发的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>本地开发</th><th>生产部署</th></tr></thead><tbody><tr><td>中间件</td><td>docker start mysql8 redis</td><td>env compose 全家桶或自建</td></tr><tr><td>应用</td><td>IDEA 里 Debug（dev profile）</td><td>容器跑 jar（prod profile）</td></tr><tr><td>配置</td><td>application-dev.yml</td><td>application-prod.yml（host 用容器名）</td></tr><tr><td>前端</td><td>npm run dev（8090，代理 8080）</td><td>打包产物给 nginx</td></tr><tr><td>日志</td><td>控制台</td><td>文件/ELK</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/knowledge/service/java-deployment.html">Java 服务部署最佳实践</a> - 通用部署流程、JVM 调优、发布与回滚（本文的&quot;最佳实践版&quot;）</li><li><a href="/knowledge/java-practice/harvest.html">收获记录</a> - 日志链路（logback → Logstash → ES）的配置细节</li><li><a href="/knowledge/service/elasticsearch.html">Elasticsearch 入门</a> - ELK 里 ES 的角色</li><li><a href="/knowledge/service/spring-boot.html">Spring Boot 入门</a> - 打包部署一节（jar 内嵌 Tomcat）</li></ul>`,45)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
